import{_ as t,o as e,c as i,ai as r}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"AI Training","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/ai-training.md","filePath":"en/guide/ai-training.md"}'),n={name:"en/guide/ai-training.md"};function o(s,a,l,c,g,d){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="ai-training" tabindex="-1">AI Training <a class="header-anchor" href="#ai-training" aria-label="Permalink to &quot;AI Training&quot;">​</a></h1><p>The AI Training page lets you collect, curate, and export training data pairs for fine-tuning language models.</p><p><strong>Sidebar item:</strong> AI Training <strong>Route:</strong> <code>/training</code></p><h2 id="what-are-training-pairs" tabindex="-1">What Are Training Pairs? <a class="header-anchor" href="#what-are-training-pairs" aria-label="Permalink to &quot;What Are Training Pairs?&quot;">​</a></h2><p>A training pair consists of a <strong>user prompt</strong> and a <strong>model response</strong>. By collecting high-quality pairs, you build a dataset that can be used to fine-tune a model to behave the way you want.</p><h2 id="how-pairs-are-collected" tabindex="-1">How Pairs Are Collected <a class="header-anchor" href="#how-pairs-are-collected" aria-label="Permalink to &quot;How Pairs Are Collected&quot;">​</a></h2><p>Training pairs are automatically captured from your interactions with the <strong>Canvas AI</strong> feature in the Tool Workshop. When the AI generates tool code, drafts improvements, or provides insights, each interaction becomes a training pair stored in IndexedDB.</p><h2 id="curating-data" tabindex="-1">Curating Data <a class="header-anchor" href="#curating-data" aria-label="Permalink to &quot;Curating Data&quot;">​</a></h2><p>The main interface shows a table of all collected training pairs. For each pair you can:</p><h3 id="accept-or-reject" tabindex="-1">Accept or Reject <a class="header-anchor" href="#accept-or-reject" aria-label="Permalink to &quot;Accept or Reject&quot;">​</a></h3><ul><li><strong>Accept</strong> — Mark the pair as high-quality training data</li><li><strong>Reject</strong> — Mark it as unsuitable (bad output, hallucination, etc.)</li></ul><h3 id="edit-responses" tabindex="-1">Edit Responses <a class="header-anchor" href="#edit-responses" aria-label="Permalink to &quot;Edit Responses&quot;">​</a></h3><p>Click on any response to edit it. This is useful when the model&#39;s output was close but needs correction — you get the right answer without starting from scratch.</p><h3 id="tagging" tabindex="-1">Tagging <a class="header-anchor" href="#tagging" aria-label="Permalink to &quot;Tagging&quot;">​</a></h3><p>Add tags to organize pairs by topic, quality level, or any custom category. Tags help you filter and export specific subsets.</p><h3 id="bulk-operations" tabindex="-1">Bulk Operations <a class="header-anchor" href="#bulk-operations" aria-label="Permalink to &quot;Bulk Operations&quot;">​</a></h3><p>Select multiple pairs to:</p><ul><li><strong>Bulk accept/reject</strong> — Set status for many pairs at once</li><li><strong>Bulk add tags</strong> — Apply a tag to all selected pairs</li><li><strong>Delete</strong> — Remove unwanted pairs</li></ul><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p>Filter the training pair list by:</p><ul><li><strong>Status</strong> — Accepted, rejected, or unreviewed</li><li><strong>Tags</strong> — Show only pairs with specific tags</li><li><strong>Search</strong> — Free-text search across prompts and responses</li></ul><h2 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h2><p>Select the pairs you want to export (or use filters to narrow down), then click <strong>Export</strong>. The exported dataset can be used with fine-tuning tools and frameworks.</p><h2 id="statistics" tabindex="-1">Statistics <a class="header-anchor" href="#statistics" aria-label="Permalink to &quot;Statistics&quot;">​</a></h2><p>The page header shows aggregate stats:</p><ul><li>Total pairs collected</li><li>Accepted vs. rejected counts</li><li>Tag distribution</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Quality over quantity</strong> — A small dataset of carefully curated pairs produces better fine-tuning results than a large noisy dataset.</li><li><strong>Edit, don&#39;t discard</strong> — If a response is 80% correct, editing it is more efficient than regenerating from scratch.</li><li><strong>Use tags strategically</strong> — Tag by capability (e.g., &quot;code-gen&quot;, &quot;api-tools&quot;, &quot;explanation&quot;) to create focused training subsets.</li></ul>',28)])])}const p=t(n,[["render",o]]);export{u as __pageData,p as default};
